namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateOnly LastInspected);

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate async data access
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Hydraulic Press", "Building A", new DateOnly(2026, 3, 15)),
            new(2, "CNC Lathe", "Building B", new DateOnly(2026, 5, 22)),
            new(3, "Forklift #7", "Warehouse", new DateOnly(2026, 1, 10)),
            new(4, "Welding Station 3", "Building A", new DateOnly(2025, 11, 30)),
            new(5, "Conveyor Belt Line 2", "Building C", new DateOnly(2026, 4, 8)),
            new(6, "Air Compressor", "Utility Room", new DateOnly(2026, 6, 1)),
            new(7, "Overhead Crane", "Building B", new DateOnly(2025, 9, 14)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject EquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToString("yyyy-MM-dd")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? equipment;
    private PersistingComponentStateSubscription persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (!ApplicationState.TryTakeFromJson<List<EquipmentItem>>("equipment", out var restored))
        {
            // First render (prerender): fetch from service
            equipment = await EquipmentService.GetEquipmentAsync();
        }
        else
        {
            // Interactive activation: reuse persisted data — no second fetch
            equipment = restored;
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("equipment", equipment);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        persistingSubscription.Dispose();
    }
}

